package com.spinplayer.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.os.Bundle;import android.util.TypedValue;import android.view.View;import android.widget.RemoteViews;import org.json.*;import java.io.*;import java.util.*;
public class SpinWidget extends AppWidgetProvider {
 public static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);Class<?>[] types={CompactWidget.class,StandardWidget.class,VinylWidget.class,CollectionWidget.class};for(int k=0;k<types.length;k++)for(int id:m.getAppWidgetIds(new ComponentName(c,types[k])))update(c,m,id,k);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle options){refresh(c);}
 static Bitmap cover(Context c,JSONObject t){if(t==null)return null;try{String p=t.optString("cover").split("\\?",2)[0];if(!p.startsWith("art/"))return null;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;return BitmapFactory.decodeFile(new File(c.getFilesDir(),p).getAbsolutePath(),o);}catch(Exception e){return null;}}
 static int accent(Context c){try{return Color.parseColor(c.getSharedPreferences("spin",0).getString("widgetAccent","#8ab4f8"));}catch(Exception e){return 0xff8ab4f8;}}
 static Bitmap square(Bitmap image){int s=240;Bitmap b=Bitmap.createBitmap(s,s,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);if(image==null){p.setColor(0xff30343f);canvas.drawRoundRect(0,0,s,s,18,18,p);p.setColor(0xffa8aeb9);p.setTextSize(30);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextAlign(Paint.Align.CENTER);canvas.drawText("SPIN",120,130,p);}else{float scale=Math.max((float)s/image.getWidth(),(float)s/image.getHeight());Matrix m=new Matrix();m.setScale(scale,scale);m.postTranslate((s-image.getWidth()*scale)/2,(s-image.getHeight()*scale)/2);BitmapShader shader=new BitmapShader(image,Shader.TileMode.CLAMP,Shader.TileMode.CLAMP);shader.setLocalMatrix(m);p.setShader(shader);canvas.drawRoundRect(0,0,s,s,18,18,p);}return b;}
 static Bitmap playIcon(Context c,boolean playing){Bitmap b=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(3);p.setColor(accent(c));canvas.drawCircle(48,48,46,p);p.setColor(0xff101820);if(playing){canvas.drawRoundRect(33,29,43,67,3,3,p);canvas.drawRoundRect(53,29,63,67,3,3,p);}else{Path path=new Path();path.moveTo(37,27);path.lineTo(69,48);path.lineTo(37,69);path.close();canvas.drawPath(path,p);}return b;}
 static void update(Context c,AppWidgetManager manager,int id,int kind){int[] layouts={R.layout.widget_compact,R.layout.widget_standard,R.layout.widget_vinyl,R.layout.widget_collection};RemoteViews v=new RemoteViews(c.getPackageName(),layouts[kind]);boolean cd="liquid-glass".equals(c.getSharedPreferences("spin",0).getString("playerAppearance","vinyl"));int opacity=c.getSharedPreferences("spin",0).getInt("widgetOpacity",100);v.setColorStateList(R.id.widget_root,"setBackgroundTintList",ColorStateList.valueOf(Color.argb(opacity*255/100,cd?33:32,cd?52:34,cd?81:39)));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);JSONArray library=MusicLibrary.load(c);PlaybackService p=PlaybackService.instance;JSONObject t=p!=null&&p.track!=null?p.track:library.optJSONObject(0);
 if(kind==3){Map<String,List<JSONObject>> albums=new LinkedHashMap<>();for(int j=0;j<library.length();j++){JSONObject a=library.optJSONObject(j);if(!LibraryEditor.album(a))continue;String key=LibraryEditor.key(a);albums.computeIfAbsent(key,x->new ArrayList<>()).add(a);}int[] slots={R.id.album0,R.id.album1,R.id.album2},arts={R.id.art0,R.id.art1,R.id.art2},names={R.id.name0,R.id.name1,R.id.name2};int width=manager.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,280);int count=Math.max(1,Math.min(3,albums.size()));float imageSize=Math.max(48,Math.min(120,(width-40f)/count-8));int x=0;for(List<JSONObject> list:albums.values()){if(x>=3)break;JSONObject first=list.get(0);v.setTextViewText(names[x],first.optString("album"));v.setImageViewBitmap(arts[x],square(cover(c,first)));v.setViewLayoutWidth(arts[x],imageSize,TypedValue.COMPLEX_UNIT_DIP);v.setViewLayoutHeight(arts[x],imageSize,TypedValue.COMPLEX_UNIT_DIP);try{Intent play=new Intent(c,PlaybackService.class).setAction("play").putExtra("payload",new JSONObject().put("queue",new JSONArray(list)).put("index",0).toString());v.setOnClickPendingIntent(slots[x],PendingIntent.getForegroundService(c,first.optInt("id"),play,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));}catch(Exception ignored){}x++;}if(x==0){v.setTextViewText(names[0],"Добавить музыку");v.setImageViewBitmap(arts[0],square(null));v.setOnClickPendingIntent(slots[0],open);x=1;}for(;x<3;x++)v.setViewVisibility(slots[x],View.GONE);
 }else{setWave(c,v);v.setTextViewText(R.id.title,t==null?"Выбери музыку":t.optString("name"));v.setTextViewText(R.id.artist,t==null?"SPIN Player":t.optString("artist"));v.setImageViewBitmap(R.id.play,playIcon(c,p!=null&&p.isPlaying()));v.setOnClickPendingIntent(R.id.title,open);v.setOnClickPendingIntent(R.id.art,open);v.setOnClickPendingIntent(R.id.play,t==null?open:PlaybackService.control(c,"toggle"));v.setOnClickPendingIntent(R.id.next,t==null?open:PlaybackService.control(c,"next"));if(kind!=0)v.setOnClickPendingIntent(R.id.previous,t==null?open:PlaybackService.control(c,"prev"));if(kind==1){int progress=0;try{if(p!=null&&p.ready&&p.player.getDuration()>0)progress=(int)(1000L*p.player.getCurrentPosition()/p.player.getDuration());}catch(Exception ignored){}v.setProgressBar(R.id.progress,1000,progress,false);}Bitmap art=cover(c,t);if(cd)v.setImageViewBitmap(R.id.art,cdArt(art));else if(kind==2)v.setImageViewBitmap(R.id.art,vinyl(c,art,p,t));else v.setImageViewBitmap(R.id.art,square(art));}manager.updateAppWidget(id,v);}
 static Bitmap cdArt(Bitmap art){
  Bitmap result=Bitmap.createBitmap(240,240,Bitmap.Config.ARGB_8888);
  Canvas cv=new Canvas(result);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
  paint.setColor(0xff324d6d);cv.drawRoundRect(4,14,236,226,26,26,paint);
  paint.setColor(0xff789bb9);cv.drawRoundRect(14,24,226,187,17,17,paint);
  paint.setShader(new SweepGradient(144,106,new int[]{0xffe5ebff,0xffa0d9e0,0xffd7bafa,0xffedebd1,0xffe5ebff},null));
  cv.drawCircle(144,106,69,paint);paint.setShader(null);
  paint.setColor(0xff243850);cv.drawCircle(144,106,12,paint);
  paint.setColor(0xff75e3ed);cv.drawCircle(209,206,5,paint);
  paint.setFilterBitmap(true);
  if(art!=null)cv.drawBitmap(square(art),null,new Rect(18,95,104,181),paint);
  return result;
 }
 static boolean waveEnabled(Context c){return c.getSharedPreferences("spin",0).getBoolean("waveEnabled",false)&&c.getSharedPreferences("spin",0).getBoolean("widgetWave",false);}
 static void setWave(Context c,RemoteViews v){
  boolean enabled=waveEnabled(c);v.setViewVisibility(R.id.audio_wave,enabled?View.VISIBLE:View.GONE);if(!enabled)return;
  Bitmap bitmap=Bitmap.createBitmap(320,48,Bitmap.Config.ARGB_8888);
  Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);paint.setColor(accent(c));paint.setStrokeWidth(2);
  String style=c.getSharedPreferences("spin",0).getString("visualStyle","spectrum");
  int count=c.getSharedPreferences("spin",0).getInt("visualDensity",32);
  PlaybackService player=PlaybackService.instance;
  boolean bars=style.equals("spectrum")||style.equals("mirror");
  float[] data=player!=null&&player.isPlaying()?(bars?player.spectrum:player.wave):new float[128];
  float step=320f/count;float[] levels=new float[count];
  for(int i=0;i<count;i++)levels[i]=Math.max(0,Math.min(1,data[i*data.length/count]));
  if(bars){for(int i=0;i<count;i++){float h=Math.max(1,levels[i]*(style.equals("mirror")?23:46));canvas.drawRoundRect(i*step,style.equals("mirror")?24-h:48-h,i*step+step*.72f,style.equals("mirror")?24+h:48,1,1,paint);}}
  else if(style.equals("dots")){for(int i=0;i<count;i++)canvas.drawCircle(i*step+step/2,24-levels[i]*20,2+levels[i]*2,paint);}
  else{
   Path path=new Path();boolean area=style.equals("area"),line=style.equals("wave"),dual=style.equals("double");
   for(int i=0;i<count;i++){float y=(area?48:24)-levels[i]*(area?46:22)*(line&&i%2==0?-1:1);if(i==0)path.moveTo(0,y);else path.lineTo(i*319f/(count-1),y);}
   if(line||dual){paint.setStyle(Paint.Style.STROKE);canvas.drawPath(path,paint);if(dual){canvas.save();canvas.scale(1,-1,160,24);canvas.drawPath(path,paint);canvas.restore();}}
   else{if(area){path.lineTo(319,48);path.lineTo(0,48);}else for(int i=count-1;i>=0;i--)path.lineTo(i*319f/(count-1),24+levels[i]*22);path.close();canvas.drawPath(path,paint);}
  }
  v.setImageViewBitmap(R.id.audio_wave,bitmap);
 }
 static void refreshWave(Context c){if(!waveEnabled(c))return;AppWidgetManager m=AppWidgetManager.getInstance(c);Class<?>[] types={CompactWidget.class,StandardWidget.class,VinylWidget.class};int[] layouts={R.layout.widget_compact,R.layout.widget_standard,R.layout.widget_vinyl};for(int k=0;k<types.length;k++){int[] ids=m.getAppWidgetIds(new ComponentName(c,types[k]));if(ids.length==0)continue;RemoteViews v=new RemoteViews(c.getPackageName(),layouts[k]);setWave(c,v);m.partiallyUpdateAppWidget(ids,v);}}
 static int albumAccent(Context c,JSONObject track){Bitmap b=cover(c,track);if(b==null)return accent(c);Bitmap small=Bitmap.createScaledBitmap(b,12,12,true);int best=accent(c);float score=-1;float[] hsv=new float[3];for(int y=0;y<12;y++)for(int x=0;x<12;x++){int color=small.getPixel(x,y);Color.colorToHSV(color,hsv);float v=hsv[1]*(hsv[2]>.2f&&hsv[2]<.95f?1:.1f);if(v>score){score=v;hsv[1]=Math.min(.55f,hsv[1]);hsv[2]=.85f;best=Color.HSVToColor(hsv);}}small.recycle();return best;}
 static Bitmap notificationArt(Context c,JSONObject t){Bitmap art=cover(c,t);Bitmap out=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);Paint p=new Paint(3);p.setColor(0xff17171b);canvas.drawCircle(160,160,156,p);if(t!=null){File texture=new File(c.getFilesDir(),"vinyl/"+t.optInt("id")+".png");Bitmap b=BitmapFactory.decodeFile(texture.getAbsolutePath());if(b!=null){canvas.save();Path clip=new Path();clip.addCircle(160,160,156,Path.Direction.CW);canvas.clipPath(clip);canvas.drawBitmap(b,null,new Rect(4,4,316,316),p);canvas.restore();b.recycle();}}p.setColor(0x553c3c45);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);for(int r=65;r<155;r+=5)canvas.drawCircle(160,160,r,p);p.setStyle(Paint.Style.FILL);p.setColor(albumAccent(c,t));canvas.drawCircle(160,160,57,p);if(art!=null){canvas.save();Path clip=new Path();clip.addCircle(160,160,52,Path.Direction.CW);canvas.clipPath(clip);canvas.drawBitmap(art,null,new Rect(108,108,212,212),p);canvas.restore();}p.setColor(0xffcccccc);canvas.drawCircle(160,160,4,p);return out;}
 static Bitmap vinyl(Context context,Bitmap cover,PlaybackService service,JSONObject track){int n=400;Bitmap b=Bitmap.createBitmap(n,n,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint paint=new Paint(3);JSONObject style=new JSONObject();try{if(track!=null)style=new JSONObject(context.getSharedPreferences("spin",0).getString("vinyl:"+track.optInt("id"),"{}"));}catch(Exception ignored){}int color=0xff121316;try{color=Color.parseColor(style.optString("color","#121316"));}catch(Exception ignored){}paint.setColor(color);c.drawCircle(180,200,166,paint);c.save();Path vinylClip=new Path();vinylClip.addCircle(180,200,166,Path.Direction.CW);c.clipPath(vinylClip);boolean hasTexture=false;try{if(track!=null){File textureFile=new File(context.getFilesDir(),"vinyl/"+track.optInt("id")+".png");if(textureFile.exists()){Bitmap texture=BitmapFactory.decodeFile(textureFile.getAbsolutePath());if(texture!=null){c.drawColor(Color.TRANSPARENT,PorterDuff.Mode.CLEAR);c.drawBitmap(texture,null,new Rect(14,34,346,366),paint);hasTexture=true;}}}}catch(Exception ignored){}String pattern=style.optString("pattern");Random rng=new Random(472);if(!hasTexture&&"splatter".equals(pattern)){paint.setColor(0xffececea);for(int i=0;i<65;i++)c.drawCircle(rng.nextInt(350),rng.nextInt(380),1+rng.nextInt(6),paint);}else if(!hasTexture&&("marble".equals(pattern)||"swirl".equals(pattern)||"geo".equals(pattern))){for(int i=0;i<12;i++){paint.setColor(i%2==0?0x509090c0:0x65000000);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth("geo".equals(pattern)?16:3+rng.nextInt(17));c.drawArc(-100+i*19,-40+i*18,450+i*12,420+i*14,i*12,230,false,paint);}paint.setStyle(Paint.Style.FILL);}c.restore();paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);paint.setColor(0x45303038);for(int r=70;r<165;r+=5)c.drawCircle(180,200,r,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(accent(context));c.drawCircle(180,200,62,paint);if(cover!=null&&!"spin".equals(style.optString("label"))){c.save();Path clip=new Path();clip.addCircle(180,200,56,Path.Direction.CW);c.clipPath(clip);c.drawBitmap(cover,null,new Rect(124,144,236,256),paint);c.restore();}else{paint.setColor(0xff202227);c.drawCircle(180,200,56,paint);paint.setColor(0xffeeeeef);paint.setTextSize(22);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));c.drawText("SPIN",180,208,paint);}double progress=0;try{if(service!=null&&service.ready)progress=(double)service.player.getCurrentPosition()/Math.max(1,service.player.getDuration());}catch(Exception ignored){}double dx=350-180,dy=200-48,d=Math.hypot(dx,dy),len=240,r=157-84*progress,angle=track==null?-.12:Math.atan2(dx,dy)-Math.acos((d*d+len*len-r*r)/(2*d*len));float tx=(float)(350-len*Math.sin(angle)),ty=(float)(48+len*Math.cos(angle));paint.setColor(0xffa8aeb9);paint.setStrokeWidth(7);c.drawLine(350,48,tx,ty,paint);paint.setColor(accent(context));c.drawCircle(tx,ty,7,paint);paint.setColor(0xff786e79);c.drawCircle(350,48,13,paint);return b;}
}
